package week_01;
import javax.swing.*;import java.awt.*;
public class frm_TanCong extends JFrame {
 private final JTextArea cipher=new JTextArea(3,58),result=new JTextArea(15,58);private final JTextField knownPlain=new JTextField("HELLO",12),knownCipher=new JTextField("RIJVS",12);
 public frm_TanCong(){super("Phân tích mật mã cổ điển");setDefaultCloseOperation(DISPOSE_ON_CLOSE);setSize(760,660);setLocationRelativeTo(null);JPanel p=new JPanel();p.setBorder(BorderFactory.createEmptyBorder(16,20,16,20));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel title=new JLabel("PHÂN TÍCH (TẤN CÔNG) MẬT MÃ CỔ ĐIỂN");title.setFont(new Font("Segoe UI",1,18));p.add(title);p.add(new JLabel("Ciphertext:"));p.add(new JScrollPane(cipher));JPanel buttons=new JPanel();JButton brute=new JButton("Brute Force Caesar"),freq=new JButton("Frequency Analysis");buttons.add(brute);buttons.add(freq);p.add(buttons);JPanel k=new JPanel(new FlowLayout(FlowLayout.LEFT));k.add(new JLabel("Bản rõ đã biết:"));k.add(knownPlain);k.add(new JLabel("Bản mã:"));k.add(knownCipher);JButton know=new JButton("Known Plaintext (Vigenère)");k.add(know);p.add(k);result.setEditable(false);p.add(new JLabel("Kết quả:"));p.add(new JScrollPane(result));brute.addActionListener(e->result.setText(AttackDemos.brute(cipher.getText())));freq.addActionListener(e->result.setText(AttackDemos.frequency(cipher.getText())));know.addActionListener(e->{try{result.setText("Khóa Vigenère suy ra: "+AttackDemos.known(knownPlain.getText(),knownCipher.getText()));}catch(Exception x){JOptionPane.showMessageDialog(this,x.getMessage());}});add(p);}
}
